WITH scored AS (SELECT id, customer_id, account_type, balance, opened_date, status, NTILE(4) OVER (ORDER BY balance, id) balance_bucket, DENSE_RANK() OVER (PARTITION BY customer_id ORDER BY balance DESC) balance_dense_rank FROM accounts) SELECT CASE WHEN balance >= 62000 THEN 'HIGH' ELSE 'LOW' END AS balance_tier, COUNT(CASE WHEN account_type = 'CREDIT' THEN 1 END) AS credit_count, SUM(CASE WHEN account_type = 'CREDIT' THEN balance_bucket ELSE 0 END) AS credit_balance_bucket, ROUND(SUM(balance_bucket) / NULLIF(COUNT(CASE WHEN account_type = 'CREDIT' THEN 1 END), 0), 2) AS balance_bucket_per_credit, SUM(CASE WHEN status = 'OPEN' THEN balance_dense_rank ELSE 0 END) AS open_balance_dense_rank FROM scored GROUP BY 1 HAVING SUM(CASE WHEN status = 'OPEN' THEN balance_dense_rank ELSE 0 END) > 0;
